"""Render rows of cells as a GitHub markdown table."""


def to_markdown(rows):
    """Lines of a markdown table for rows (the first row is the header), joined with newlines."""
    if not rows or not rows[0]:
        raise ValueError("table needs a header row with at least one cell")
    width = len(rows[0])
    for i, row in enumerate(rows):
        if len(row) != width:
            raise ValueError(f"row {i} has {len(row)} cells, header has {width}")
    lines = [_line(rows[0]), _line(["---"] * width)]
    lines += [_line(row) for row in rows[1:]]
    return "\n".join(lines)


def _line(cells):
    return "| " + " | ".join(c.strip().replace("|", "\\|") for c in cells) + " |"
